def semver_sort(versions):
    def parse_version(version_str):
        # Split on '+' to remove build metadata
        version_without_build = version_str.split('+')[0]

        # Split on '-' to separate core version from pre-release
        if '-' in version_without_build:
            core_part, prerelease_part = version_without_build.split('-', 1)
        else:
            core_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, core_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease = tuple(identifiers)
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def compare_key(version_str):
        major, minor, patch, prerelease = parse_version(version_str)

        # Convert prerelease to a comparable form
        if prerelease is None:
            # Version without prerelease sorts after the same version with prerelease
            prerelease_key = (1,)  # Higher value
        else:
            # Convert each identifier to a comparable form
            identifiers = []
            for identifier in prerelease:
                if identifier.isdigit():
                    # All-digit identifiers compare numerically and sort before non-digit identifiers
                    identifiers.append((0, int(identifier)))
                else:
                    # Other identifiers compare by ASCII order
                    identifiers.append((1, identifier))
            prerelease_key = (0, tuple(identifiers))  # Lower value for presence of prerelease

        return (major, minor, patch, prerelease_key)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

